# New hypothesis: Use a majority voting / smoothing filter
# Keep value if most neighbors agree with you
# With some minimum support threshold

def neighbor_filter(grid, target_val, min_support=3):
    """Keep cell if most same-valued neighbors >= min_support"""
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # First pass: compute for each cell what its final value should be
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_val:
                # Count orthogonal neighbors with same value
                same_count = 0
                diff_count = 0
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == target_val:
                            same_count += 1
                        else:
                            diff_count += 1

                # If we don't have enough same-value neighbors, flip to background
                if same_count < min_support:
                    result[r][c] = 1

    return result

print("Testing neighbor filter (min_support varies):")
