    print(f"  min_support={min_s}: {'MATCH!' if match else 'NO MATCH'}")

# Also test with a two-pass approach (considering already changed cells)
def iterative_neighbor_filter(grid, target_val, min_support=3, max_iter=10):
    """Iteratively apply neighbor filter until convergence"""
    current = [row[:] for row in grid]
    for _ in range(max_iter):
        new_grid = [row[:] for row in current]
        changed_any = False

        for r in range(h):
            for c in range(w):
                if current[r][c] == target_val:
                    same_count = sum(1 for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                                    if 0 <= r+dr < h and 0 <= c+dc < w 
                                    and current[r+dr][c+dc] == target_val)
                    if same_count < min_support:
                        new_grid[r][c] = 1
                        changed_any = True

        if not changed_any:
            break
        current = new_grid

    return current

print("\nTesting iterative neighbor filter:")
