    result = iterative_neighbor_filter(demo_input, 4, min_s)
    match = result == demo_output
    print(f"  min_support={min_s}: {'MATCH!' if match else 'NO MATCH'}")

# What about checking diagonal neighbors too?
def eight_way_neighbor_filter(grid, target_val, min_support=4):
    """Use 8-way neighborhood including diagonals"""
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_val:
                # Count all 8 neighbors
                same_count = 0
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == target_val:
                                same_count += 1

                if same_count < min_support:
                    result[r][c] = 1

    return result

